"""P7 notifications generated by real P5/P6 events, and the guarded bank-change evidence path."""

from uuid import UUID, uuid4

from sqlalchemy import text

from tests.contracts.examples import evidence
from tests.db import test_p6_approval
from tests.db.test_p6_approval import (
    as_user,
    code,
    decide,
    member,
    post,
    prepare,
    reviewed,
    step_up,
)
from tests.db.test_p6_execution import drain, execute

case = test_p6_approval.case  # shared evaluated-deal fixture


def titles(s, account):
    as_user(s, account)
    return [n["title"] for n in s["read"]("/notifications?limit=100")["items"]]


def test_approval_revocation_and_execution_notify_recipients(case, postgres, config):
    s = case
    owner = s["account"]
    risk, _ = member(postgres, config, s, "risk_officer")
    viewer, _ = member(postgres, config, s, "viewer")
    mid = reviewed(s)["identity"]["message_id"]
    first = prepare(s, "send_message", [mid])
    approval = decide(s, first, step_up(s, first)["grant_id"])
    s["write"](f"/approvals/{approval['id']}/revoke", dict(**s["versions"](), reason="Pause for a call."))
    bundle = prepare(s, "send_message", [mid])
    approval = decide(s, bundle, step_up(s, bundle)["grant_id"])
    accepted = execute(s, bundle, approval)
    drain(postgres)
    assert s["read"](f"/operations/{accepted['operation_id']}")["status"] == "succeeded"
    seen = titles(s, risk)
    assert seen.count("Approval requested") == 2 and seen.count("Approval granted") == 2
    assert seen.count("Approval revoked") == 1 and seen.count("Sandbox execution succeeded") == 1
    # The creator/approver/revoker is not told about their own action; execution is async.
    assert titles(s, owner) == ["Sandbox execution succeeded"]
    assert titles(s, viewer) == []  # read-only members are not workflow recipients
    as_user(s, owner)
    # Dedupe: recovering the same run cannot produce a second success notice.
    with postgres["database"].tenant(risk.token, owner.business_id) as (c, _):
        assert c.execute(text("SELECT count(*) FROM notification WHERE code='EXECUTION-SUCCEEDED'")).scalar_one() == 1
        assert c.execute(text("SELECT count(DISTINCT event_key) FROM notification")).scalar_one() == len(seen)


def supplier_reply(s, body):
    """Supplier party on an evaluated deal, an exact draft to it, then a reply (P5 pipeline)."""
    deal_id = s["deal"]["id"]
    revision = lambda: s["versions"]()["expected_financial_revision"]  # noqa: E731
    supplier = s["write"]("/payees", dict(expected_financial_revision=revision(), payee=dict(
        name="P7 supplier " + uuid4().hex[:6], kind="supplier", category="other", terms_days=30, terms_note=None,
        delay_tolerance_note=None, risk_rating=None, known_domains=["supplier.test"])))
    original = s["read"]("/constraints")["items"][0]
    owner = {k: v for k, v in original["owner"].items() if k not in {"constraints_id", "version"}}
    policy = s["write"]("/constraints", dict(
        expected_financial_revision=revision(), reserve_minor=original["reserve_minor"], owner=owner,
        strategy_space=dict(deposit_pcts=[0], deposit_lead_days=0,
                            extensions=[dict(days=0, surcharge_bps=0), dict(days=30, surcharge_bps=0)],
                            offer_ids=[], stages=1),
        scenarios=original["scenarios"], make_default=False))
    current = s["read"](f"/deals/{deal_id}")
    cost = dict(event_id=None, cost_key="supplier-cost", event_date="2026-11-02", amount_minor="1000000",
                kind="supplier_payment", is_deferrable=True, incremental=True, nonincremental_reason=None,
                invoice_ref=None, payee_id=supplier["id"], original_obligation_id="p7-supplier-obligation",
                evidence=[evidence()])
    s["write"](f"/deals/{deal_id}", dict(**s["versions"](), inputs=current["inputs"] | {
        "constraints_id": policy["id"], "costs": [cost]}), method="PATCH")
    review = s["read"](f"/deals/{deal_id}/review")
    confirmation = s["write"](f"/deals/{deal_id}/confirm", dict(
        **s["versions"](), snapshot_hash=review["snapshot_hash"], confirmed_field_ids=review["required_field_ids"],
        acknowledged_warning_codes=[f["code"] for f in review["findings"] if not f["blocking"]]))
    evaluated = s["finish"](s["write"](f"/deals/{deal_id}/evaluations", dict(
        **s["versions"](), snapshot_id=confirmation["snapshot_id"]), 202))
    option = next(o for o in evaluated["option_catalogue"]
                  if o["hard_feasible"] and o["parameters"]["extension"]["days"] == 30)
    message = s["finish"](s["write"](f"/deals/{deal_id}/drafts", dict(
        **s["versions"](), evaluation_id=evaluated["id"], option_key=option["option_key"],
        party_id=supplier["id"], party_role="supplier", recipient="contact@supplier.test"), 202))
    reply = s["finish"](s["write"](f"/deals/{deal_id}/replies", dict(
        **s["versions"](), ask_message_id=message["identity"]["message_id"], party_id=supplier["id"],
        body=body), 202))
    return supplier, reply


def test_bank_change_hold_clears_only_with_exact_reply_verified_account_and_t3(case, postgres, config):
    s = case
    owner = s["account"]
    lead, _ = member(postgres, config, s, "commercial_lead")
    deal_id = s["deal"]["id"]
    supplier, reply = supplier_reply(s, "Please use our changed bank account for the next payment.")
    assert reply["bank_change"]
    as_user(s, lead)
    assert "Bank change hold" in [n["title"] for n in s["read"]("/notifications")["items"]]
    assert "Reply received" in [n["title"] for n in s["read"]("/notifications")["items"]]
    as_user(s, owner)
    with postgres["database"].tenant(owner.token, owner.business_id) as (c, _):
        flag_id = c.execute(text("SELECT id FROM deal_flag WHERE deal_id=:d AND code='P5-BANK-CHANGE'"),
                            dict(d=UUID(deal_id))).scalar_one()
    accounts = f"/payees/{supplier['id']}/accounts"
    account = s["write"](accounts, dict(expected_financial_revision=s["versions"]()["expected_financial_revision"],
                                        bank_name="New bank", account_number="NEWACCT55501234"), 201)
    path = f"/deals/{deal_id}/flags/{flag_id}/resolve"

    def resolve(reply_id=None, account_id=None, written="Called the supplier on the number on file; confirmed.",
                status=None):
        body = dict(**s["versions"](), evidence=evidence(), reason="Verified out of band")
        if account_id is not None:
            body["bank_verification"] = dict(reply_id=reply_id, account_id=account_id, written_evidence=written)
        r = post(s, path, body)
        if status is not None:
            assert r.status_code == status, r.text
        return r

    # A generic override, a pending account and a commercial lead cannot clear the hold.
    assert code(resolve(status=409)) == "BANK_VERIFICATION_REQUIRED"
    assert code(resolve(reply["id"], account["id"], status=409)) == "ACCOUNT_NOT_VERIFIED"
    account = s["write"](f"{accounts}/{account['id']}/verify", dict(
        expected_version=account["version"], expected_financial_revision=s["versions"]()["expected_financial_revision"],
        evidence=evidence()))
    as_user(s, lead)
    assert resolve(reply["id"], account["id"], status=403)
    as_user(s, owner)
    assert resolve(str(uuid4()), account["id"], status=404)
    # Another party's verified account does not match the reply's party.
    other = s["write"]("/payees", dict(expected_financial_revision=s["versions"]()["expected_financial_revision"],
                                       payee=dict(name="P7 other " + uuid4().hex[:6], kind="supplier",
                                                  category="other", terms_days=None, terms_note=None,
                                                  delay_tolerance_note=None, risk_rating=None, known_domains=[])))
    foreign = s["write"](f"/payees/{other['id']}/accounts", dict(
        expected_financial_revision=s["versions"]()["expected_financial_revision"], bank_name="Other",
        account_number="OTHER0000001"), 201)
    foreign = s["write"](f"/payees/{other['id']}/accounts/{foreign['id']}/verify", dict(
        expected_version=foreign["version"], expected_financial_revision=s["versions"]()["expected_financial_revision"],
        evidence=evidence()))
    assert code(resolve(reply["id"], foreign["id"], status=409)) == "ACCOUNT_PARTY_MISMATCH"
    assert resolve(reply["id"], account["id"], written="too short", status=422)
    resolved = resolve(reply["id"], account["id"], status=200).json()
    assert not any(f["code"] == "P5-BANK-CHANGE" and f["blocking"] for f in resolved["findings"])
    with postgres["database"].tenant(owner.token, owner.business_id) as (c, _):
        row = c.execute(text("SELECT r.actor_user_id,r.source_reply_id,r.account_id FROM bank_verification_resolution r "
                             "WHERE r.flag_id=:f"), dict(f=flag_id)).mappings().one()
        assert (row["actor_user_id"], str(row["source_reply_id"]), str(row["account_id"])) == (
            owner.user_id, reply["id"], account["id"])


def bank_finding(findings):
    return next((f for f in findings if f["code"] == "P5-BANK-CHANGE"), None)


def test_bank_change_hold_resolves_through_the_api_projected_flag_id(case, postgres, config):
    """Whole UI path: the flag id comes from DealView/Review findings, never from SQL."""
    s = case
    owner = s["account"]
    lead, _ = member(postgres, config, s, "commercial_lead")
    deal_id = s["deal"]["id"]
    supplier, reply = supplier_reply(s, "Please use our changed bank account for the next payment.")
    assert reply["bank_change"]
    view = s["read"](f"/deals/{deal_id}")
    finding = bank_finding(view["findings"])
    assert finding and finding["blocking"] and finding["flag_id"]
    # Every DealView finding projects a stored flag, so each carries its flag_resolve id.
    assert all(f["flag_id"] and f["flag_id"].isdigit() for f in view["findings"])
    review = s["read"](f"/deals/{deal_id}/review")
    assert bank_finding(review["findings"])["flag_id"] == finding["flag_id"]
    # Findings computed from inputs are cleared by correcting input, not by flag_resolve.
    assert all(f["flag_id"] is None for f in review["findings"] if f["code"] != "P5-BANK-CHANGE"
               and f["code"] not in {g["code"] for g in view["findings"]})
    with postgres["database"].tenant(owner.token, owner.business_id) as (c, _):
        stored = c.execute(text("SELECT id FROM deal_flag WHERE deal_id=:d AND code='P5-BANK-CHANGE'"),
                           dict(d=UUID(deal_id))).scalar_one()
    assert finding["flag_id"] == str(stored)
    path = f"/deals/{deal_id}/flags/{finding['flag_id']}/resolve"
    accounts = f"/payees/{supplier['id']}/accounts"
    account = s["write"](accounts, dict(expected_financial_revision=s["versions"]()["expected_financial_revision"],
                                        bank_name="New bank", account_number="NEWACCT55507777"), 201)

    def resolve(verification, status):
        body = dict(**s["versions"](), evidence=evidence(), reason="Verified out of band")
        if verification is not None:
            body["bank_verification"] = verification
        r = post(s, path, body)
        assert r.status_code == status, r.text
        return r

    written = "Called the supplier on the number already on file; they confirmed the change."
    exact = lambda account_id, text_=written: dict(  # noqa: E731
        reply_id=reply["id"], account_id=account_id, written_evidence=text_)
    # No bank-verification block, missing/short written evidence and a pending account are refused.
    assert code(resolve(None, 409)) == "BANK_VERIFICATION_REQUIRED"
    resolve(dict(reply_id=reply["id"], account_id=account["id"]), 422)
    resolve(exact(account["id"], "too short"), 422)
    assert code(resolve(exact(account["id"]), 409)) == "ACCOUNT_NOT_VERIFIED"
    account = s["write"](f"{accounts}/{account['id']}/verify", dict(
        expected_version=account["version"], expected_financial_revision=s["versions"]()["expected_financial_revision"],
        evidence=evidence()))
    # A T2 member (commercial lead) cannot clear it even with the verified account and evidence.
    as_user(s, lead)
    assert code(resolve(exact(account["id"]), 403)) == "FORBIDDEN"
    as_user(s, owner)
    assert bank_finding(s["read"](f"/deals/{deal_id}")["findings"])["blocking"]
    # Current T3 (owner) with the exact reply, verified account and written evidence clears it.
    resolved = resolve(exact(account["id"]), 200).json()
    assert bank_finding(resolved["findings"]) is None
    assert bank_finding(s["read"](f"/deals/{deal_id}")["findings"]) is None
    assert bank_finding(s["read"](f"/deals/{deal_id}/review")["findings"]) is None
    again = post(s, path, dict(**s["versions"](), evidence=evidence(), reason="Again",
                               bank_verification=exact(account["id"])))
    assert again.status_code == 409  # one bank resolution per flag (SQL guard); hold stays cleared
    assert bank_finding(s["read"](f"/deals/{deal_id}")["findings"]) is None


def test_bodyless_commands_accept_absent_null_and_empty_object(case, postgres, config):
    """decision_export, cash_export and notification_read: absent/null/{} accepted, fields rejected."""
    s = case
    owner = s["account"]
    lead, _ = member(postgres, config, s, "commercial_lead")
    supplier_reply(s, "Please use our changed bank account for the next payment.")
    deal_id = s["deal"]["id"]

    def send(path, body):
        headers = s["headers"] | {"Idempotency-Key": str(uuid4())}
        if body is _ABSENT:
            return s["client"].post(s["base"] + path, headers=headers)
        return s["client"].post(s["base"] + path, content=body,
                                headers=headers | {"Content-Type": "application/json"})

    as_user(s, lead)
    notification_id = s["read"]("/notifications")["items"][0]["id"]
    as_user(s, owner)
    targets = [(f"/deals/{deal_id}/decision-export", 201, owner), ("/cash-events/export", 201, owner),
               (f"/notifications/{notification_id}/read", 200, lead)]
    for path, status, actor in targets:
        as_user(s, actor)
        for body in (_ABSENT, b"null", b"{}", b" { } "):
            r = send(path, body)
            assert r.status_code == status, (path, body, r.text)
        for body in (b'{"unexpected": 1}', b"[]", b'"x"', b"0", b"not json"):
            r = send(path, body)
            assert r.status_code == 422 and code(r) == "INVALID_INPUT", (path, body, r.text)
    # Absent, null and {} are one command: replaying a key with another empty form returns the cache.
    as_user(s, owner)
    key = str(uuid4())
    path = s["base"] + "/cash-events/export"
    first = s["client"].post(path, headers=s["headers"] | {"Idempotency-Key": key})
    replay = s["client"].post(path, content=b"{}", headers=s["headers"] | {
        "Idempotency-Key": key, "Content-Type": "application/json"})
    assert first.status_code == 201 and replay.status_code == 201 and replay.json()["id"] == first.json()["id"]


_ABSENT = object()
